List<Question> _legacyHoliday(String topic,String level) {
  if (topic == 'Christmas Nativity') return [...?newReviewedQuestionBanks['Holidays']?[topic]?[level], ...?curatedAdditions['Holidays']?[topic]?[level]];
  if (topic == 'Christmas Carols') return christmasCarolsQuestionBanks['Holidays']?[topic]?[level] ?? <Question>[];
  final reviewed = newReviewedQuestionBanks['Holidays']?[topic]?[level];
  if (reviewed != null && reviewed.isNotEmpty) return reviewed;
  return expandedQuestionBanks['Holidays']?[topic]?[level] ?? <Question>[];
}

